head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > weekStartsOn]<br/>Calendar 컴포넌트의 시작 요일을 설정합니다.",
    "validation" : [
        "미설정 시 기본값 '0' (일요일) 로 동작하여 요일 헤더가 '일,월,화,수,목,금,토' 순서로 표시됩니다.",
        "'0' 설정 시 일요일을 시작으로 '일,월,화,수,목,금,토' 순서로 요일 헤더가 표시됩니다.",
        "'1' 설정 시 월요일을 시작으로 '월,화,수,목,금,토,일' 순서로 요일 헤더가 표시됩니다.",
        "'2' 설정 시 화요일을 시작으로 '화,수,목,금,토,일,월' 순서로 요일 헤더가 표시됩니다.",
        "'3' 설정 시 수요일을 시작으로 '수,목,금,토,일,월,화' 순서로 요일 헤더가 표시됩니다.",
        "'4' 설정 시 목요일을 시작으로 '목,금,토,일,월,화,수' 순서로 요일 헤더가 표시됩니다.",
        "'5' 설정 시 금요일을 시작으로 '금,토,일,월,화,수,목' 순서로 요일 헤더가 표시됩니다.",
        "'6' 설정 시 토요일을 시작으로 '토,일,월,화,수,목,금' 순서로 요일 헤더가 표시됩니다.",
        "'0~6' 이외의 값을 설정 시 팝업 달력의 날짜 영역이 정상적으로 표시되지 않을 수 있습니다.",
        "날짜 셀에 부여되는 요일 CSS 클래스 ('w2calendar_day_' + 요일인덱스) 는 weekStartsOn 속성에 의해 재배열됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        weekStartsOn : con_weekStartsOn.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// [요일 헤더 순서] thead 의 7개 요일 셀 textContent — weekStartsOn 에 의한 순서 재배열
scwin.getDayHeaderOrder = function () {
    let dayCells = target1.render.querySelectorAll('thead tr > *');
    let texts = [];
    dayCells.forEach((el) => {
        let innerDiv = el.querySelector('div');
        let title = innerDiv ? innerDiv.getAttribute('title') : el.getAttribute('title');
        texts.push(title || el.textContent.trim());
    });
    // validation: weekStartsOn 값에 따라 요일 헤더 순서가 변경됨
    wf_body_bottom.getObj("scwin").setReturnValue("[요일 헤더 순서] [" + texts.join(',') + "]");
}



// [날짜 셀 CSS 클래스 재배열] tbody 두번째 행의 날짜 셀 'w2calendar_day_{인덱스}' 클래스 순서
scwin.getDateCellDayClass = function () {
    let secondRow = target1.render.querySelector('tbody tr:nth-child(2)');
    let dateCells = secondRow ? secondRow.querySelectorAll('td[class*="w2calendar_col_date"]') : [];
    if (dateCells.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("[날짜 셀 요일 CSS 클래스] 없음 (날짜 영역 미표시)");
        return;
    }
    let dayClasses = [];
    for (let i = 0; i < Math.min(7, dateCells.length); i++) {
        let match = dateCells[i].className.match(/w2calendar_day_(\d+)/);
        dayClasses.push(match ? ('w2calendar_day_' + match[1]) : '없음');
    }
    // validation: 날짜 셀에 부여되는 요일 CSS 클래스 ('w2calendar_day_' + 요일인덱스) 는 weekStartsOn 에 의해 재배열됨
    wf_body_bottom.getObj("scwin").setReturnValue("[날짜 셀 두번째 행 요일 CSS 클래스 순서] [" + dayClasses.join(',') + "]");
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getDayHeaderOrder();
    scwin.getDateCellDayClass();
}
